   332	static avifBool avifCodecDecodeInputGetSamples(avifCodecDecodeInput * decodeInput, avifSampleTable * sampleTable, size_t sizeHint)
   333	{
   334	    uint32_t sampleSizeIndex = 0;
   335	    for (uint32_t chunkIndex = 0; chunkIndex < sampleTable->chunks.count; ++chunkIndex) {
   336	        avifSampleTableChunk * chunk = &sampleTable->chunks.chunk[chunkIndex];
   337	
   338	        // First, figure out how many samples are in this chunk
   339	        uint32_t sampleCount = 0;
   340	        for (int sampleToChunkIndex = sampleTable->sampleToChunks.count - 1; sampleToChunkIndex >= 0; --sampleToChunkIndex) {
   341	            avifSampleTableSampleToChunk * sampleToChunk = &sampleTable->sampleToChunks.sampleToChunk[sampleToChunkIndex];
   342	            if (sampleToChunk->firstChunk <= (chunkIndex + 1)) {
   343	                sampleCount = sampleToChunk->samplesPerChunk;
   344	                break;
   345	            }
   346	        }
   347	        if (sampleCount == 0) {
   348	            // chunks with 0 samples are invalid
   349	            return AVIF_FALSE;
   350	        }
   351	
   352	        uint64_t sampleOffset = chunk->offset;
   353	        for (uint32_t sampleIndex = 0; sampleIndex < sampleCount; ++sampleIndex) {
   354	            uint32_t sampleSize = sampleTable->allSamplesSize;
   355	            if (sampleSize == 0) {
   356	                if (sampleSizeIndex >= sampleTable->sampleSizes.count) {
   357	                    // We've run out of samples to sum
   358	                    return AVIF_FALSE;
   359	                }
   360	                avifSampleTableSampleSize * sampleSizePtr = &sampleTable->sampleSizes.sampleSize[sampleSizeIndex];
   361	                sampleSize = sampleSizePtr->size;
   362	            }
   363	
   364	            avifDecodeSample * sample = (avifDecodeSample *)avifArrayPushPtr(&decodeInput->samples);
   365	            sample->offset = sampleOffset;
   366	            sample->size = sampleSize;
   367	            sample->sync = AVIF_FALSE; // to potentially be set to true following the outer loop
   368	
   369	            if (sizeHint && ((sampleOffset + sampleSize) > (uint64_t)sizeHint)) {
   370	                return AVIF_FALSE;
   371	            }
   372	
   373	            sampleOffset += sampleSize;
   374	            ++sampleSizeIndex;
   375	        }
   376	    }
   377	
   378	    // Mark appropriate samples as sync
   379	    for (uint32_t syncSampleIndex = 0; syncSampleIndex < sampleTable->syncSamples.count; ++syncSampleIndex) {
   380	        uint32_t frameIndex = sampleTable->syncSamples.syncSample[syncSampleIndex].sampleNumber - 1; // sampleNumber is 1-based
   381	        if (frameIndex < decodeInput->samples.count) {
   382	            decodeInput->samples.sample[frameIndex].sync = AVIF_TRUE;
   383	        }
   384	    }
   385	
   386	    // Assume frame 0 is sync, just in case the stss box is absent in the BMFF. (Unnecessary?)
   387	    if (decodeInput->samples.count > 0) {
   388	        decodeInput->samples.sample[0].sync = AVIF_TRUE;
   389	    }
   390	    return AVIF_TRUE;
   391	}
